class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        n = len(hamsters)
        used = [False] * n
        buckets = 0
        for i, ch in enumerate(hamsters):
            if ch != 'H':
                continue
            if i > 0 and used[i - 1]:
                continue
            if i + 1 < n and hamsters[i + 1] == '.':
                used[i + 1] = True
                buckets += 1
            elif i > 0 and hamsters[i - 1] == '.':
                used[i - 1] = True
                buckets += 1
            else:
                return -1
        return buckets

