        for (int i = 0; i + 2 < n; i++) {
            if (hamsters[i] == 'H' && hamsters[i + 1] == '.' && hamsters[i + 2] == 'H'
                && !paired[i] && !paired[i + 2]) {
                paired[i] = paired[i + 2] = true;
                pairs++;
            }
        }
        return total - pairs;
    }
};

