class Solution {
    public int minimumBuckets(String hamsters) {
        int n = hamsters.length();
        char[] c = hamsters.toCharArray();
        for (int i = 0; i < n; i++) {
            if (c[i] == 'H' &&
                (i + 1 == n || c[i + 1] == 'H') &&
                (i == 0 || c[i - 1] == 'H'))
                return -1;
        }

        int total = 0;
        for (char ch : c)
            if (ch == 'H') total++;

        boolean[] paired = new boolean[n];
        int pairs = 0;
        for (int i = 0; i + 2 < n; i++) {
            if (c[i] == 'H' && c[i + 1] == '.' && c[i + 2] == 'H'
                && !paired[i] && !paired[i + 2]) {
                paired[i] = paired[i + 2] = true;
                pairs++;
            }
        }
        return total - pairs;
    }
};

